class _RealDiscoverScreenState extends State<RealDiscoverScreen>{late Future<List<Map<String,dynamic>>> future;int cardIndex=0;@override void initState(){super.initState();future=OpenBackend.instance.discover();}void reload()=>setState((){cardIndex=0;future=OpenBackend.instance.discover();});@override Widget build(BuildContext context)=>SafeArea(child:Padding(padding:const EdgeInsets.fromLTRB(20,18,20,6),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(children:[const Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Merhaba 👋',style:TextStyle(color:ui.OpenApp.muted,fontWeight:FontWeight.w600)),SizedBox(height:2),Text('Keşfet ✨',style:TextStyle(fontSize:31,fontWeight:FontWeight.w900,letterSpacing:-1))])),IconButton(onPressed:reload,icon:const Icon(Icons.refresh_rounded))]),const SizedBox(height:16),Expanded(child:FutureBuilder<List<Map<String,dynamic>>>(future:future,builder:(context,snapshot){if(snapshot.connectionState!=ConnectionState.done)return const Center(child:CircularProgressIndicator());if(snapshot.hasError)return _StateCard(title:'Keşfet yüklenemedi',subtitle:'${snapshot.error}',action:reload);final profiles=snapshot.data??const <Map<String,dynamic>>[];if(profiles.isEmpty)return _StateCard(title:'Henüz keşfedecek profil yok.',subtitle:'Yeni profiller tamamlandığında burada görünecek.',action:reload);if(cardIndex>=profiles.length)return _StateCard(title:'Şimdilik bu kadar ✨',subtitle:'Yeni profiller için tekrar kontrol edebilirsin.',action:reload);final profile=profiles[cardIndex];return _ProfileCard(profile:profile,onSkip:()=>setState(()=>cardIndex++),onKey:()=>_answer(profile));}))])));Future<void> _answer(Map<String,dynamic> profile)async{final raw=profile['profile_questions'];final questions=raw is List?raw.whereType<Map>().map((e)=>Map<String,dynamic>.from(e)).toList():<Map<String,dynamic>>[];questions.sort((a,b)=>((a['position'] as num?)?.toInt()??0).compareTo((b['position'] as num?)?.toInt()??0))